$src = @'
using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Drawing.Text;
public static class FindingIcons {
 static Color C(string s){return ColorTranslator.FromHtml(s);}
 static Pen P(string s,float w){Pen p=new Pen(C(s),w);p.StartCap=LineCap.Round;p.EndCap=LineCap.Round;p.LineJoin=LineJoin.Round;return p;}
 static void L(Graphics g,string c,float w,params PointF[] p){using(var x=P(c,w))g.DrawLines(x,p);}
 static void B(Graphics g,string c,float w,PointF a,PointF b,PointF d,PointF e){using(var x=P(c,w))g.DrawBezier(x,a,b,d,e);}
 static void E(Graphics g,string f,string s,float sw,float x,float y,float w,float h){using(var b=new SolidBrush(C(f)))g.FillEllipse(b,x,y,w,h);using(var p=P(s,sw))g.DrawEllipse(p,x,y,w,h);}
 static void R(Graphics g,string f,string s,float sw,float x,float y,float w,float h,float r=8){using(var q=new GraphicsPath()){q.AddArc(x,y,r,r,180,90);q.AddArc(x+w-r,y,r,r,270,90);q.AddArc(x+w-r,y+h-r,r,r,0,90);q.AddArc(x,y+h-r,r,r,90,90);q.CloseFigure();using(var b=new SolidBrush(C(f)))g.FillPath(b,q);using(var p=P(s,sw))g.DrawPath(p,q);}}
 static void Poly(Graphics g,string f,string s,float sw,params PointF[] a){using(var q=new GraphicsPath()){q.AddPolygon(a);using(var b=new SolidBrush(C(f)))g.FillPath(b,q);using(var p=P(s,sw))g.DrawPath(p,q);}}
 static void Base(Graphics g,string a){g.SmoothingMode=SmoothingMode.AntiAlias;g.PixelOffsetMode=PixelOffsetMode.HighQuality;g.CompositingQuality=CompositingQuality.HighQuality;g.TextRenderingHint=TextRenderingHint.AntiAliasGridFit;g.Clear(Color.Transparent);using(var b=new SolidBrush(Color.FromArgb(25,15,35,55)))g.FillEllipse(b,12,16,104,104);using(var b=new LinearGradientBrush(new Rectangle(10,8,108,108),Color.White,C("#EAF2F8"),LinearGradientMode.Vertical))g.FillEllipse(b,10,8,108,108);using(var p=P("#17324D",5))g.DrawEllipse(p,10,8,108,108);using(var p=P(a,5))g.DrawEllipse(p,18,16,92,92);}
 public static void Save(string n,string file){string a="#2563EB";switch(n){case "aislador-danado":a="#DC2626";break;case "conductor-cortado":a="#EA580C";break;case "cruceta-danada":a="#B45309";break;case "empalme-irregular":a="#7C3AED";break;case "estructura-danada":a="#DC2626";break;case "otro":a="#2563EB";break;case "poda-preventiva":a="#16A34A";break;case "poste-chocado":a="#EA580C";break;case "poste-desaplomado":a="#D97706";break;case "retensado-linea":a="#0F766E";break;case "tirante-proteccion":a="#CA8A04";break;case "vegetacion-cercana":a="#15803D";break;}
 using(var b=new Bitmap(128,128,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(b)){Base(g,a);string nvy="#17324D",blue="#2E6FD8",sky="#9BD5F2",wood="#A8612B",gold="#F4A62A",red="#E14335",green="#31A85B",purple="#6256C9",gray="#6F8294";
 switch(n){
 case "aislador-danado":L(g,nvy,8,new PointF(64,28),new PointF(64,101));R(g,sky,nvy,4,49,40,30,12,5);R(g,"#DDF3FF",nvy,4,43,53,42,12,5);R(g,sky,nvy,4,49,66,30,12,5);L(g,red,6,new PointF(81,35),new PointF(70,49),new PointF(78,57),new PointF(66,71),new PointF(73,79));break;
 case "conductor-cortado":B(g,blue,9,new PointF(18,57),new PointF(29,50),new PointF(40,64),new PointF(50,57));B(g,blue,9,new PointF(78,57),new PointF(89,50),new PointF(100,64),new PointF(110,57));Poly(g,gold,nvy,3,new PointF(60,39),new PointF(70,51),new PointF(64,57),new PointF(74,68),new PointF(58,61),new PointF(64,53));L(g,red,4,new PointF(53,39),new PointF(48,31));L(g,red,4,new PointF(76,38),new PointF(82,30));break;
 case "cruceta-danada":L(g,wood,10,new PointF(62,37),new PointF(62,102));L(g,nvy,6,new PointF(25,46),new PointF(88,46));L(g,nvy,5,new PointF(31,39),new PointF(31,53));L(g,nvy,5,new PointF(46,39),new PointF(46,53));L(g,nvy,5,new PointF(76,39),new PointF(76,53));L(g,red,7,new PointF(90,46),new PointF(104,46));L(g,red,5,new PointF(95,38),new PointF(89,47),new PointF(98,54),new PointF(92,62));break;
 case "empalme-irregular":B(g,blue,8,new PointF(18,50),new PointF(30,50),new PointF(39,61),new PointF(48,61));B(g,blue,8,new PointF(80,54),new PointF(91,54),new PointF(98,67),new PointF(110,67));R(g,"#D9E8FF",nvy,5,46,46,36,32,8);L(g,purple,6,new PointF(56,51),new PointF(73,73));L(g,red,5,new PointF(64,39),new PointF(64,32));L(g,red,5,new PointF(64,84),new PointF(64,92));break;
 case "estructura-danada":L(g,wood,11,new PointF(62,26),new PointF(62,101));L(g,nvy,6,new PointF(25,46),new PointF(99,46));E(g,gold,nvy,3,23,36,13,13);E(g,gold,nvy,3,89,36,13,13);L(g,nvy,4,new PointF(42,46),new PointF(42,57));L(g,nvy,4,new PointF(82,46),new PointF(82,57));L(g,red,6,new PointF(71,62),new PointF(60,73),new PointF(69,81),new PointF(58,94));L(g,nvy,6,new PointF(43,101),new PointF(81,101));break;
 case "otro":Poly(g,"#DCEBFF",blue,6,new PointF(64,25),new PointF(91,44),new PointF(86,73),new PointF(64,99),new PointF(42,73),new PointF(37,44));E(g,blue,blue,1,49,32,30,30);using(var f=new Font("Segoe UI",31,FontStyle.Bold,GraphicsUnit.Pixel))using(var z=new SolidBrush(Color.White))g.DrawString("?",f,z,52,28);E(g,gold,nvy,3,55,81,18,18);break;
 case "poda-preventiva":L(g,wood,8,new PointF(61,65),new PointF(61,101));Poly(g,green,nvy,4,new PointF(61,22),new PointF(40,51),new PointF(50,51),new PointF(34,73),new PointF(88,73),new PointF(72,51),new PointF(82,51));L(g,gold,6,new PointF(82,81),new PointF(98,97));L(g,nvy,5,new PointF(98,97),new PointF(104,90));L(g,nvy,5,new PointF(98,97),new PointF(90,104));break;
 case "poste-chocado":Poly(g,gold,nvy,4,new PointF(45,20),new PointF(55,23),new PointF(42,74),new PointF(33,96),new PointF(26,91),new PointF(35,68));L(g,nvy,5,new PointF(35,40),new PointF(84,40));L(g,nvy,4,new PointF(41,36),new PointF(41,46));L(g,nvy,4,new PointF(57,36),new PointF(57,46));L(g,nvy,4,new PointF(78,36),new PointF(78,46));R(g,"#386BD8",nvy,5,45,72,62,26,10);Poly(g,"#A9E0F5",nvy,3,new PointF(54,75),new PointF(70,75),new PointF(77,84),new PointF(52,84));E(g,nvy,nvy,1,55,91,12,12);E(g,nvy,nvy,1,86,91,12,12);L(g,red,5,new PointF(27,59),new PointF(18,53));L(g,red,5,new PointF(25,68),new PointF(14,68));L(g,gold,5,new PointF(43,60),new PointF(49,55),new PointF(54,62));break;
 case "poste-desaplomado":L(g,wood,9,new PointF(53,23),new PointF(42,102));L(g,gray,3,new PointF(78,22),new PointF(78,102));L(g,nvy,6,new PointF(29,42),new PointF(88,49));L(g,nvy,4,new PointF(35,37),new PointF(35,47));L(g,nvy,4,new PointF(78,43),new PointF(78,53));E(g,"#D7F4E2",green,4,68,59,18,18);E(g,green,green,1,73,64,8,8);L(g,nvy,7,new PointF(29,103),new PointF(70,103));break;
 case "retensado-linea":L(g,wood,8,new PointF(27,37),new PointF(27,100));L(g,wood,8,new PointF(101,37),new PointF(101,100));L(g,nvy,5,new PointF(17,45),new PointF(40,45));L(g,nvy,5,new PointF(88,45),new PointF(111,45));B(g,blue,6,new PointF(40,45),new PointF(53,62),new PointF(75,62),new PointF(88,45));L(g,green,5,new PointF(49,78),new PointF(29,78));Poly(g,green,green,1,new PointF(28,78),new PointF(39,70),new PointF(39,86));L(g,green,5,new PointF(79,78),new PointF(99,78));Poly(g,green,green,1,new PointF(100,78),new PointF(89,70),new PointF(89,86));break;
 case "tirante-proteccion":L(g,wood,9,new PointF(56,24),new PointF(56,102));L(g,nvy,4,new PointF(31,45),new PointF(84,45));L(g,gray,5,new PointF(60,51),new PointF(98,98));R(g,"#FDE68A",nvy,4,72,66,16,25,4);L(g,red,4,new PointF(73,73),new PointF(85,81));L(g,red,4,new PointF(72,83),new PointF(84,91));L(g,nvy,6,new PointF(38,102),new PointF(80,102));break;
 case "vegetacion-cercana":L(g,nvy,5,new PointF(18,38),new PointF(110,38));L(g,nvy,5,new PointF(18,48),new PointF(110,48));L(g,wood,8,new PointF(82,55),new PointF(82,102));E(g,"#5FC879",nvy,4,50,64,38,31);E(g,"#7DDD91",nvy,4,36,73,33,26);E(g,"#38AC5E",nvy,4,63,77,32,25);L(g,gold,5,new PointF(72,29),new PointF(77,24));L(g,gold,5,new PointF(89,29),new PointF(94,24));break;
 }
 b.Save(file,ImageFormat.Png);
 }
 }
}
'@
Add-Type -TypeDefinition $src -ReferencedAssemblies System.Drawing
$names = @('aislador-danado','conductor-cortado','cruceta-danada','empalme-irregular','estructura-danada','otro','poda-preventiva','poste-chocado','poste-desaplomado','retensado-linea','tirante-proteccion','vegetacion-cercana')
foreach($name in $names){[FindingIcons]::Save($name,(Join-Path $PSScriptRoot ($name+'.png')))}
